class Solution {
    public int arrayPairSum(int[] nums) {
        int[] counts = new int[20001];
        for (int num : nums) {
            counts[num + 10000]++;
        }

        int answer = 0;
        boolean takeAsMinimum = true;
        for (int value = -10000; value <= 10000; value++) {
            int index = value + 10000;
            while (counts[index] > 0) {
                if (takeAsMinimum) {
                    answer += value;
                }
                takeAsMinimum = !takeAsMinimum;
                counts[index]--;
            }
        }
        return answer;
    }
}

class Solution {
    public int arrayPairSum(int[] nums) {
        java.util.PriorityQueue<Integer> heap = new java.util.PriorityQueue<>();
        for (int num : nums) {
            heap.offer(num);
        }

        int answer = 0;
        while (!heap.isEmpty()) {
            int smaller = heap.poll();
            heap.poll();
            answer += smaller;
        }
        return answer;
    }
}

class Solution {
    public int arrayPairSum(int[] nums) {
        int[] buffer = new int[nums.length];
        mergeSort(nums, buffer, 0, nums.length);

        int answer = 0;
        for (int i = 0; i < nums.length; i += 2) {
            answer += nums[i];
        }
        return answer;
    }

    private void mergeSort(int[] nums, int[] buffer, int left, int right) {
        if (right - left <= 1) {
            return;
        }

        int middle = left + (right - left) / 2;
        mergeSort(nums, buffer, left, middle);
        mergeSort(nums, buffer, middle, right);

        int i = left;
        int j = middle;
        int k = left;
        while (i < middle && j < right) {
            if (nums[i] <= nums[j]) {
                buffer[k++] = nums[i++];
            } else {
                buffer[k++] = nums[j++];
            }
        }
        while (i < middle) {
            buffer[k++] = nums[i++];
        }
        while (j < right) {
            buffer[k++] = nums[j++];
        }
        for (i = left; i < right; i++) {
            nums[i] = buffer[i];
        }
    }
}
